public final class MainActivity extends Activity {
    private static final int REQUEST_AUDIO = 1001;
    private int BG = Color.rgb(8,26,48), SURFACE = Color.rgb(18,43,72), ALT = Color.rgb(25,55,87), MINT = Color.rgb(94,234,212), MUTED = Color.rgb(168,184,204), TEXT = Color.WHITE;
    private final List<LibraryDbHelper.Track> tracks = new ArrayList<>(), recent = new ArrayList<>();
    private final ExecutorService executor = Executors.newSingleThreadExecutor();
    private LibraryDbHelper database; private LinearLayout rootView, pageHost, bottomNav, miniPlayer; private EditText search; private TextView pageTitle, pageSubtitle, status, activeLyrics; private ScrollView lyricsScroll; private SeekBar playerProgress; private boolean userSeeking, darkMode; private int page, playingIndex = -1, sortMode = 0; private boolean favoritesOnly; private List<LrcParser.Line> currentLyrics = new ArrayList<>();
    private final BroadcastReceiver progressReceiver = new BroadcastReceiver() { @Override public void onReceive(Context context, Intent intent) { if (PlaybackService.ACTION_PROGRESS.equals(intent.getAction())) { int position=intent.getIntExtra("position",0), duration=intent.getIntExtra("duration",0); if(playerProgress!=null&&!userSeeking&&duration>0) playerProgress.setProgress((int)(position*1000L/duration)); updateLyrics(position); } } };
    @Override public void onCreate(Bundle state) { super.onCreate(state); darkMode=getSharedPreferences("mintune_settings",MODE_PRIVATE).getBoolean("dark_mode",true); applyThemePalette(); if (Build.VERSION.SDK_INT >= 30) getWindow().setDecorFitsSystemWindows(true); getWindow().setStatusBarColor(BG); getWindow().setNavigationBarColor(BG); database = new LibraryDbHelper(this); android.content.IntentFilter progressFilter = new android.content.IntentFilter(PlaybackService.ACTION_PROGRESS); if (Build.VERSION.SDK_INT >= 33) registerReceiver(progressReceiver, progressFilter, Context.RECEIVER_NOT_EXPORTED); else registerReceiver(progressReceiver, progressFilter); buildShell(); if (hasAudioPermission()) loadData(); else requestAudioPermission(); }
    private void applyThemePalette(){if(darkMode){BG=Color.rgb(8,26,48);SURFACE=Color.rgb(18,43,72);ALT=Color.rgb(25,55,87);MINT=Color.rgb(94,234,212);MUTED=Color.rgb(168,184,204);TEXT=Color.WHITE;}else{BG=Color.rgb(242,248,249);SURFACE=Color.rgb(255,255,255);ALT=Color.rgb(219,237,239);MINT=Color.rgb(0,112,105);MUTED=Color.rgb(76,96,105);TEXT=Color.rgb(18,39,50);}getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);if(rootView!=null)rootView.setBackgroundColor(BG);}
    private void buildShell() { final int pad=dp(18); LinearLayout root=column(); rootView=root; root.setBackgroundColor(BG); root.setPadding(pad,dp(12),pad,dp(8)); root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(pad,dp(12)+i.getSystemWindowInsetTop(),pad,dp(8)+i.getSystemWindowInsetBottom());return i;}); LinearLayout header=column(), titleRow=row(), copy=column(); pageTitle=text("今日聆听",25,TEXT); pageTitle.setTypeface(null,1); pageSubtitle=text("你的私人音乐空间",13,MUTED); copy.addView(pageTitle); copy.addView(pageSubtitle,lp(-1,dp(24))); titleRow.addView(copy,lp(0,-2,1)); TextView logo=text("M",32,MINT); logo.setGravity(Gravity.CENTER); logo.setBackground(glassBackground(ALT)); titleRow.addView(logo,lp(dp(52),dp(52))); header.addView(titleRow); root.addView(header); pageHost=column(); root.addView(pageHost,lp(-1,0,1)); miniPlayer=row(); miniPlayer.setVisibility(View.GONE); root.addView(miniPlayer,lp(-1,dp(58))); bottomNav=row(); bottomNav.setPadding(0,dp(8),0,0); root.addView(bottomNav,lp(-1,dp(62))); setContentView(root); switchPage(0); }
    private void switchPage(int target) { page=target; pageHost.removeAllViews(); String[] titles={"今日聆听","音乐库","歌单","设置","正在播放","播放队列"}, subs={"你的私人音乐空间","搜索和管理本地音乐","整理你的音乐收藏","让播放体验更贴近你","播放详情","当前播放队列"}; pageTitle.setText(titles[target]); pageSubtitle.setText(subs[target]); if(target==0) renderHome(); else if(target==1) renderLibrary(); else if(target==2) renderPlaylists(); else if(target==3) renderSettings(); else if(target==4) renderPlayer(); else renderQueue(); renderBottomNav(); }
    private void renderBottomNav() { bottomNav.removeAllViews(); String[] labels={"今日聆听","音乐库","歌单","设置"}, icons={"⌂","♫","▣","⚙"}; for(int i=0;i<4;i++){final int tab=i; LinearLayout item=column(); item.setGravity(Gravity.CENTER); TextView ic=text(icons[i],20,page==i?MINT:MUTED); ic.setGravity(Gravity.CENTER); item.addView(ic,lp(-1,dp(25))); TextView label=text(labels[i],11,page==i?MINT:MUTED); label.setGravity(Gravity.CENTER); item.addView(label,lp(-1,dp(22))); item.setOnClickListener(v->switchPage(tab)); bottomNav.addView(item,lp(0,dp(52),1));} }
    private void renderHome() { ScrollView scroll=new ScrollView(this); LinearLayout body=column(); body.setPadding(0,dp(18),0,dp(18)); scroll.addView(body); pageHost.addView(scroll,lp(-1,0,1)); LinearLayout hero=card(); TextView ht=text(tracks.isEmpty()?"还没有音乐":"准备好继续聆听",23,TEXT); ht.setTypeface(null,1); hero.addView(ht); TextView sub=text(tracks.isEmpty()?"前往音乐库扫描设备中的本地音频，开始你的第一次聆听。":"本地音乐、歌单和播放记录都保存在设备上。",14,MUTED); sub.setPadding(0,dp(8),0,dp(14)); hero.addView(sub); Button act=button(tracks.isEmpty()?"去扫描音乐":"打开音乐库"); act.setOnClickListener(v->switchPage(1)); hero.addView(act,lp(-1,dp(44))); body.addView(hero); body.addView(section("概览")); LinearLayout stats=row(); stats.addView(stat("歌曲",String.valueOf(tracks.size())),lp(0,dp(84),1)); stats.addView(stat("歌单",String.valueOf(database.playlists().size())),lp(0,dp(84),1)); stats.addView(stat("最近播放",String.valueOf(recent.size())),lp(0,dp(84),1)); body.addView(stats); body.addView(section("最近聆听")); if(recent.isEmpty()) body.addView(text("还没有播放记录",14,MUTED),lp(-1,dp(48))); else addRows(body,recent,5); body.addView(section("快捷入口")); Button lists=button("管理我的歌单"); lists.setOnClickListener(v->switchPage(2)); body.addView(lists,lp(-1,dp(44))); }
    private void renderPlayer() { Button back=button("‹ 返回"); back.setOnClickListener(v->switchPage(0)); pageHost.addView(back,lp(-1,dp(42))); LibraryDbHelper.Track track=currentTrack(); if(track==null){pageHost.addView(text("还没有正在播放的歌曲",16,MUTED),lp(-1,dp(160)));return;} ScrollView scroll=new ScrollView(this); LinearLayout body=column(); body.setGravity(Gravity.CENTER_HORIZONTAL); ImageView cover=new ImageView(this); cover.setBackground(glassBackground(ALT)); loadCover(cover,track); body.addView(cover,lp(dp(250),dp(250))); TextView title=text(track.title,23,TEXT); title.setGravity(Gravity.CENTER); title.setTypeface(null,1); body.addView(title,lp(-1,dp(44))); TextView meta=text(track.artist+" · "+track.album,14,MUTED); meta.setGravity(Gravity.CENTER); body.addView(meta); playerProgress=new SeekBar(this); playerProgress.setMax(1000); playerProgress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean fromUser){} public void onStartTrackingTouch(SeekBar bar){userSeeking=true;} public void onStopTrackingTouch(SeekBar bar){userSeeking=false;startService(new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_SEEK).putExtra("progress",bar.getProgress()));}}); body.addView(playerProgress,lp(-1,dp(42))); LinearLayout controls=row(); Button previous=button("上一首"); previous.setOnClickListener(v->startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_PREVIOUS))); Button pause=button("播放 / 暂停"); pause.setOnClickListener(v->startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_TOGGLE))); Button next=button("下一首"); next.setOnClickListener(v->startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_NEXT))); controls.addView(previous,lp(0,dp(48),1)); controls.addView(pause,lp(0,dp(48),1)); controls.addView(next,lp(0,dp(48),1)); body.addView(controls); currentLyrics=new ArrayList<>(); activeLyrics=text("暂无歌词",15,MUTED); activeLyrics.setPadding(dp(12),dp(12),dp(12),dp(12)); lyricsScroll=new ScrollView(this); lyricsScroll.setBackground(glassBackground(SURFACE)); lyricsScroll.addView(activeLyrics,lp(-1,-2)); body.addView(lyricsScroll,lp(-1,dp(180))); if(track.lrcPath!=null)executor.execute(()->{try{String content=new String(java.nio.file.Files.readAllBytes(new File(track.lrcPath).toPath()),java.nio.charset.StandardCharsets.UTF_8);currentLyrics=LrcParser.parse(content);runOnUiThread(()->updateLyrics(0));}catch(Exception ignored){}}); Button lyrics=button(track.lrcPath==null?"暂无 LRC 文件":"查看完整歌词"); lyrics.setOnClickListener(v->showLyrics(track)); body.addView(lyrics,lp(-1,dp(44))); Button queue=button("打开播放队列"); queue.setOnClickListener(v->switchPage(5)); body.addView(queue,lp(-1,dp(44))); scroll.addView(body); pageHost.addView(scroll,lp(-1,0,1)); }
    private void renderQueue() { Button back=button("‹ 返回播放详情"); back.setOnClickListener(v->switchPage(4)); pageHost.addView(back,lp(-1,dp(42))); ScrollView scroll=new ScrollView(this); LinearLayout list=column(); addRows(list,tracks,tracks.size()); scroll.addView(list); pageHost.addView(scroll,lp(-1,0,1)); }
    private LibraryDbHelper.Track currentTrack(){return playingIndex>=0&&playingIndex<tracks.size()?tracks.get(playingIndex):null;}
    private android.app.Dialog glassDialog(String title){android.app.Dialog dialog=new android.app.Dialog(this);LinearLayout panel=card();panel.setPadding(dp(20),dp(16),dp(20),dp(16));TextView heading=text(title,19,TEXT);heading.setTypeface(null,1);panel.addView(heading);dialog.setContentView(panel);dialog.setCanceledOnTouchOutside(true);dialog.show();if(dialog.getWindow()!=null){dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setDimAmount(.58f);dialog.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.88f),-2);}return dialog;}
    private LinearLayout dialogPanel(android.app.Dialog dialog){return (LinearLayout)dialog.findViewById(android.R.id.content).getChildAt(0);}
    private Button dialogButton(LinearLayout panel,String label,View.OnClickListener listener){Button b=button(label);b.setOnClickListener(listener);panel.addView(b,lp(-1,dp(44)));return b;}
    private void showLyrics(LibraryDbHelper.Track track){if(track.lrcPath==null){Toast.makeText(this,"没有找到同名 LRC 歌词",Toast.LENGTH_SHORT).show();return;}try{String content=new String(java.nio.file.Files.readAllBytes(new File(track.lrcPath).toPath()),java.nio.charset.StandardCharsets.UTF_8);android.app.Dialog dialog=glassDialog("歌词 · "+track.title);LinearLayout panel=dialogPanel(dialog);TextView lyrics=text(content.isEmpty()?"歌词为空":content,15,MUTED);lyrics.setPadding(0,dp(10),0,dp(10));panel.addView(lyrics,lp(-1,dp(280)));dialogButton(panel,"关闭",v->dialog.dismiss());}catch(Exception e){Toast.makeText(this,"歌词读取失败",Toast.LENGTH_SHORT).show();}}
    private void renderLibrary() { LinearLayout actions=row(); Button scan=button("扫描音乐"); scan.setOnClickListener(v->scanMediaStore()); actions.addView(scan,lp(0,dp(44),1)); Button filter=button("收藏"); filter.setOnClickListener(v->{favoritesOnly=!favoritesOnly;refreshLibraryRows();}); LinearLayout.LayoutParams fp=lp(0,dp(44),1); fp.setMargins(dp(6),0,0,0); actions.addView(filter,fp); Button sort=button("排序"); sort.setOnClickListener(v->showSortDialog()); LinearLayout.LayoutParams sp=lp(0,dp(44),1); sp.setMargins(dp(6),0,0,0); actions.addView(sort,sp); pageHost.addView(actions); search=new EditText(this); search.setHint("搜索歌曲、艺人或专辑"); search.setTextColor(TEXT); search.setHintTextColor(MUTED); search.setTextSize(15); search.setSingleLine(true); search.setInputType(InputType.TYPE_CLASS_TEXT); search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){} public void onTextChanged(CharSequence s,int a,int b,int c){refreshLibraryRows();} public void afterTextChanged(android.text.Editable e){}}); pageHost.addView(search,lp(-1,dp(52))); status=text(tracks.size()+" 首歌曲",13,MINT); status.setPadding(0,dp(10),0,dp(10)); pageHost.addView(status); ScrollView scroll=new ScrollView(this); LinearLayout list=column(); list.setTag("library-list"); scroll.addView(list); pageHost.addView(scroll,lp(-1,0,1)); refreshLibraryRows(); }
    private void refreshLibraryRows() { if(page!=1)return; View view=pageHost.findViewWithTag("library-list"); if(!(view instanceof LinearLayout))return; LinearLayout list=(LinearLayout)view; list.removeAllViews(); String q=search==null?"":search.getText().toString().trim().toLowerCase(Locale.ROOT); List<LibraryDbHelper.Track> visible=new ArrayList<>(); for(LibraryDbHelper.Track t:tracks)if((!favoritesOnly||t.favorite)&&(q.isEmpty()||(t.title+" "+t.artist+" "+t.album).toLowerCase(Locale.ROOT).contains(q)))visible.add(t); visible.sort((a,b)->sortMode==1?Long.compare(b.duration,a.duration):sortMode==2?a.artist.compareToIgnoreCase(b.artist):a.title.compareToIgnoreCase(b.title)); addRows(list,visible,visible.size()); if(visible.isEmpty())list.addView(text("还没有找到音乐\n点击上方“扫描音乐”导入设备歌曲",16,MUTED),lp(-1,dp(180))); }
    private void showSortDialog(){android.app.Dialog dialog=glassDialog("排序音乐");LinearLayout panel=dialogPanel(dialog);String[] choices={"歌曲名称","时长","艺人"};for(int i=0;i<choices.length;i++){final int choice=i;dialogButton(panel,choices[i],v->{sortMode=choice;dialog.dismiss();refreshLibraryRows();});}dialogButton(panel,"取消",v->dialog.dismiss());}
    private void renderPlaylists() { Button create=button("＋ 创建歌单"); create.setOnClickListener(v->showCreatePlaylist()); pageHost.addView(create,lp(-1,dp(44))); ScrollView scroll=new ScrollView(this); LinearLayout list=column(); scroll.addView(list); pageHost.addView(scroll,lp(-1,0,1)); List<LibraryDbHelper.Playlist> pls=database.playlists(); if(pls.isEmpty())list.addView(text("还没有歌单\n点击上方创建你的第一个歌单",16,MUTED),lp(-1,dp(180))); for(LibraryDbHelper.Playlist p:pls){LinearLayout c=card(); TextView n=text(p.name,18,TEXT); n.setTypeface(null,1); c.addView(n); c.addView(text(p.count+" 首歌曲",13,MUTED)); LinearLayout buttons=row(); Button play=button("播放"); play.setOnClickListener(v->{List<LibraryDbHelper.Track> items=database.playlistTracks(p.id); if(!items.isEmpty())play(items.get(0),items);}); buttons.addView(play,lp(0,dp(40),1)); Button more=button("管理"); more.setOnClickListener(v->showPlaylistActions(p)); LinearLayout.LayoutParams mp=lp(0,dp(40),1); mp.setMargins(dp(8),0,0,0); buttons.addView(more,mp); c.addView(buttons); list.addView(c,lp(-1,-2));} }
    private void renderSettings() { ScrollView scroll=new ScrollView(this); LinearLayout body=column(); body.setPadding(0,dp(16),0,dp(16)); scroll.addView(body); pageHost.addView(scroll,lp(-1,0,1)); body.addView(section("外观")); body.addView(setting("主题模式",darkMode?"深色模式":"浅色模式",v->showThemeDialog())); body.addView(section("播放与音质")); body.addView(setting("均衡器","十段原生均衡器和预设曲线",v->showEqualizerDialog())); body.addView(setting("播放服务","MediaSession、通知栏和后台自动下一首",null)); body.addView(section("本地音乐")); body.addView(setting("扫描设备音乐","读取本地音频、封面和同名 LRC 歌词",v->scanMediaStore())); body.addView(setting("存储空间",tracks.size()+" 首歌曲 · 数据保存在本机",v->showStorageDialog())); body.addView(setting("备份与恢复","备份歌曲索引、歌单和收藏数据",v->showBackupDialog())); body.addView(section("诊断")); body.addView(setting("诊断日志","查看或清除本地播放和扫描日志",v->showLogDialog())); body.addView(section("关于 Mintune")); body.addView(setting("关于 Mintune","本地优先音乐播放器 · 版本 0.4.855",v->showAbout())); body.addView(setting("开源许可","感谢使用的开源项目",null)); }
    private void addRows(LinearLayout parent,List<LibraryDbHelper.Track> items,int limit) { for(int i=0;i<Math.min(limit,items.size());i++){LibraryDbHelper.Track t=items.get(i); LinearLayout row=row(); row.setPadding(dp(10),dp(5),dp(5),dp(5)); row.setBackground(glassBackground(SURFACE)); ImageView art=new ImageView(this); art.setBackgroundColor(ALT); loadCover(art,t); row.addView(art,lp(dp(52),dp(52))); TextView copy=text((t.uri.equals(currentUri())?"▶  ":"○  ")+t.title+"\n     "+t.artist+" · "+t.album,15,TEXT); copy.setGravity(Gravity.CENTER_VERTICAL); copy.setOnClickListener(v->play(t,tracks)); row.addView(copy,lp(0,dp(58),1)); TextView favorite=text(t.favorite?"♥":"♡",24,t.favorite?MINT:MUTED); favorite.setGravity(Gravity.CENTER); favorite.setOnClickListener(v->{database.setFavorite(t.uri,!t.favorite);loadData();}); row.addView(favorite,lp(dp(42),dp(58))); Button more=button("⋮"); more.setOnClickListener(v->showTrackMenu(t)); row.addView(more,lp(dp(44),dp(52))); LinearLayout.LayoutParams p=lp(-1,dp(68)); p.setMargins(0,0,0,dp(6)); parent.addView(row,p);} }
    private void loadCover(ImageView target,LibraryDbHelper.Track track){if(track.coverPath!=null&&new File(track.coverPath).isFile()){target.setImageURI(android.net.Uri.fromFile(new File(track.coverPath)));return;} executor.execute(()->{android.graphics.Bitmap bitmap=CoverResolver.embedded(this,track.uri);if(bitmap!=null)runOnUiThread(()->target.setImageBitmap(bitmap));});}
    private void showTrackMenu(LibraryDbHelper.Track track){
        final android.app.Dialog dialog=new android.app.Dialog(this);
        LinearLayout panel=card(); panel.setPadding(dp(20),dp(16),dp(20),dp(16));
        TextView heading=text(track.title,19,TEXT); heading.setTypeface(null,1); panel.addView(heading);
        panel.addView(text(track.artist+" · "+track.album,13,MUTED),lp(-1,dp(30)));
        String[] actions={track.favorite?"取消收藏":"收藏","添加到歌单","播放", "查看歌词"};
        for(int i=0;i<actions.length;i++){final int action=i;Button item=button(actions[i]); item.setOnClickListener(v->{dialog.dismiss();if(action==0){database.setFavorite(track.uri,!track.favorite);loadData();}else if(action==1)showAddToPlaylist(track);else if(action==2)play(track,tracks);else showLyrics(track);});panel.addView(item,lp(-1,dp(44)));}
        Button cancel=button("取消");cancel.setOnClickListener(v->dialog.dismiss());panel.addView(cancel,lp(-1,dp(44)));
        dialog.setContentView(panel);dialog.setCanceledOnTouchOutside(true);android.view.Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setDimAmount(0.55f);window.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.88f),-2);}dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.88f),-2);
    }
    private void showAddToPlaylist(LibraryDbHelper.Track track){
        List<LibraryDbHelper.Playlist> playlists=database.playlists();
        if(playlists.isEmpty()){showCreatePlaylist();return;}
        final android.app.Dialog dialog=new android.app.Dialog(this);LinearLayout panel=card();panel.setPadding(dp(20),dp(16),dp(20),dp(16));TextView heading=text("添加到歌单",19,TEXT);heading.setTypeface(null,1);panel.addView(heading);panel.addView(text(track.title,13,MUTED),lp(-1,dp(30)));
        for(LibraryDbHelper.Playlist playlist:playlists){final LibraryDbHelper.Playlist target=playlist;Button item=button(target.name+"（"+target.count+" 首）");item.setOnClickListener(v->{database.addToPlaylist(target.id,track.uri,target.count);dialog.dismiss();Toast.makeText(this,"已添加到 "+target.name,Toast.LENGTH_SHORT).show();if(page==2)switchPage(2);});panel.addView(item,lp(-1,dp(44)));}
        Button cancel=button("取消");cancel.setOnClickListener(v->dialog.dismiss());panel.addView(cancel,lp(-1,dp(44)));dialog.setContentView(panel);dialog.setCanceledOnTouchOutside(true);dialog.show();if(dialog.getWindow()!=null){dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setDimAmount(.55f);dialog.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.88f),-2);}
    }
    private String currentUri(){return playingIndex>=0&&playingIndex<tracks.size()?tracks.get(playingIndex).uri:"";}
    private TextView section(String s){TextView t=text(s,17,TEXT);t.setTypeface(null,1);t.setPadding(0,dp(20),0,dp(10));return t;}
    private LinearLayout stat(String a,String b){LinearLayout c=card();TextView v=text(b,22,MINT);v.setTypeface(null,1);c.addView(v);c.addView(text(a,12,MUTED));return c;}
    private LinearLayout setting(String a,String b,View.OnClickListener l){LinearLayout c=card();c.setOnClickListener(l);c.addView(text(a,16,TEXT));c.addView(text(b,13,MUTED));return c;}
    private LinearLayout card(){LinearLayout c=column();c.setPadding(dp(14),dp(12),dp(14),dp(12));c.setBackground(glassBackground(SURFACE));return c;}
    private void showCreatePlaylist(){android.app.Dialog dialog=glassDialog("创建歌单");LinearLayout panel=dialogPanel(dialog);EditText input=new EditText(this);input.setHint("歌单名称");input.setTextColor(TEXT);input.setHintTextColor(MUTED);panel.addView(input,lp(-1,dp(54)));dialogButton(panel,"创建",v->{String n=input.getText().toString().trim();if(!n.isEmpty()){database.createPlaylist(n);dialog.dismiss();switchPage(2);}});dialogButton(panel,"取消",v->dialog.dismiss());}
    private void showPlaylistActions(LibraryDbHelper.Playlist p){android.app.Dialog dialog=glassDialog(p.name);LinearLayout panel=dialogPanel(dialog);dialogButton(panel,"重命名",v->{dialog.dismiss();android.app.Dialog rename=glassDialog("重命名歌单");LinearLayout rp=dialogPanel(rename);EditText input=new EditText(this);input.setText(p.name);input.setTextColor(TEXT);rp.addView(input,lp(-1,dp(54)));dialogButton(rp,"保存",x->{String n=input.getText().toString().trim();if(!n.isEmpty())database.renamePlaylist(p.id,n);rename.dismiss();switchPage(2);});dialogButton(rp,"取消",x->rename.dismiss());});dialogButton(panel,"删除",v->{database.deletePlaylist(p.id);dialog.dismiss();switchPage(2);});dialogButton(panel,"取消",v->dialog.dismiss());}
    private void showStorageDialog(){android.app.Dialog dialog=glassDialog("存储空间");LinearLayout panel=dialogPanel(dialog);panel.addView(text("音乐元数据、歌单和播放历史均保存在本地。\n\n当前歌曲："+tracks.size()+" 首",14,MUTED),lp(-1,dp(90)));dialogButton(panel,"清理诊断日志",v->{new File(getFilesDir(),"mintune-diagnostics.log").delete();dialog.dismiss();Toast.makeText(this,"诊断日志已清理",Toast.LENGTH_SHORT).show();});dialogButton(panel,"知道了",v->dialog.dismiss());}
    private void showBackupDialog(){android.app.Dialog dialog=glassDialog("备份与恢复");LinearLayout panel=dialogPanel(dialog);dialogButton(panel,"导出本地备份",v->{dialog.dismiss();backupDatabase();});dialogButton(panel,"从本地备份恢复",v->{dialog.dismiss();restoreDatabase();});dialogButton(panel,"取消",v->dialog.dismiss());}
    private void backupDatabase(){try{File source=getDatabasePath("mintune.db"), target=new File(getExternalFilesDir(null),"mintune-backup.db");copyFile(source,target);Toast.makeText(this,"备份已保存到应用存储",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"备份失败",Toast.LENGTH_SHORT).show();}}
    private void restoreDatabase(){try{File source=new File(getExternalFilesDir(null),"mintune-backup.db");if(!source.isFile()){Toast.makeText(this,"没有找到备份文件",Toast.LENGTH_SHORT).show();return;}copyFile(source,getDatabasePath("mintune.db"));loadData();Toast.makeText(this,"恢复完成",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"恢复失败",Toast.LENGTH_SHORT).show();}}
    private void copyFile(File source,File target)throws java.io.IOException{try(java.io.InputStream in=new java.io.FileInputStream(source);java.io.OutputStream out=new java.io.FileOutputStream(target)){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))>=0)out.write(buffer,0,n);}}
    private void showLogDialog(){File log=new File(getFilesDir(),"mintune-diagnostics.log");android.app.Dialog dialog=glassDialog("诊断日志");LinearLayout panel=dialogPanel(dialog);panel.addView(text("日志文件："+log.getAbsolutePath()+"\n大小："+log.length()+" bytes\n\n"+(log.isFile()?"已启用本地诊断记录。":"暂无诊断日志。"),14,MUTED),lp(-1,dp(130)));dialogButton(panel,"清除",v->{log.delete();dialog.dismiss();Toast.makeText(this,"日志已清除",Toast.LENGTH_SHORT).show();});dialogButton(panel,"关闭",v->dialog.dismiss());}
    private void showThemeDialog(){final android.app.Dialog dialog=new android.app.Dialog(this);LinearLayout panel=card();panel.setPadding(dp(20),dp(16),dp(20),dp(16));TextView heading=text("主题模式",19,TEXT);heading.setTypeface(null,1);panel.addView(heading);Button dark=button("深色模式");dark.setOnClickListener(v->{setThemeMode(true);dialog.dismiss();});panel.addView(dark,lp(-1,dp(46)));Button light=button("浅色模式");light.setOnClickListener(v->{setThemeMode(false);dialog.dismiss();});panel.addView(light,lp(-1,dp(46)));Button cancel=button("取消");cancel.setOnClickListener(v->dialog.dismiss());panel.addView(cancel,lp(-1,dp(46)));dialog.setContentView(panel);dialog.setCanceledOnTouchOutside(true);dialog.show();if(dialog.getWindow()!=null){dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setDimAmount(.55f);dialog.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.88f),-2);}}
    private void setThemeMode(boolean dark){darkMode=dark;getSharedPreferences("mintune_settings",MODE_PRIVATE).edit().putBoolean("dark_mode",dark).apply();applyThemePalette();switchPage(page);}
    private void showAbout(){android.app.Dialog dialog=glassDialog("Mintune");LinearLayout panel=dialogPanel(dialog);panel.addView(text("本地优先音乐播放器\n版本 0.4.855\n\n你的音乐、歌单和播放记录默认保存在设备本地。",15,MUTED),lp(-1,dp(150)));dialogButton(panel,"知道了",v->dialog.dismiss());}
    private void showEqualizerDialog(){android.app.Dialog dialog=glassDialog("均衡器");LinearLayout panel=dialogPanel(dialog);Switch enabled=new Switch(this);enabled.setText("启用十段均衡器");enabled.setTextColor(TEXT);enabled.setChecked(true);panel.addView(enabled);String[] bands={"31","63","125","250","500","1k","2k","4k","8k","16k"};for(int i=0;i<10;i++){final int band=i;LinearLayout line=row();line.addView(text(bands[i]+" Hz",12,MUTED),lp(dp(62),dp(42)));SeekBar seek=new SeekBar(this);seek.setMax(24);seek.setProgress(12);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean u){if(u)sendEqualizer(band,p-12);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});line.addView(seek,lp(0,dp(42),1));panel.addView(line);}enabled.setOnCheckedChangeListener((b,c)->sendEqualizerEnabled(c));dialogButton(panel,"重置",v->{for(int i=0;i<10;i++)sendEqualizer(i,0);});dialogButton(panel,"流行预设",v->{int[] preset={3,2,1,0,-1,-1,0,1,2,3};for(int i=0;i<10;i++)sendEqualizer(i,preset[i]);});dialogButton(panel,"关闭",v->dialog.dismiss());}
    private void sendEqualizer(int band,float gain){startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_SET_EQ).putExtra("band",band).putExtra("gainDb",gain).putExtra("enabled",true));}
    private void sendEqualizerEnabled(boolean e){startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_SET_EQ).putExtra("band",-1).putExtra("enabled",e));}
    private void loadData(){executor.execute(()->{List<LibraryDbHelper.Track> a=database.all(),b=database.recentTracks();runOnUiThread(()->{tracks.clear();tracks.addAll(a);recent.clear();recent.addAll(b);switchPage(page);});});}
    private void scanMediaStore(){statusMessage("正在扫描设备音乐…");executor.execute(()->{String[] cols={MediaStore.Audio.Media._ID,MediaStore.Audio.Media.TITLE,MediaStore.Audio.Media.ARTIST,MediaStore.Audio.Media.ALBUM,MediaStore.Audio.Media.DURATION,MediaStore.Audio.Media.DATA,MediaStore.Audio.Media.DATE_MODIFIED};int n=0;try(Cursor c=getContentResolver().query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,cols,MediaStore.Audio.Media.IS_MUSIC+" != 0",null,MediaStore.Audio.Media.TITLE+" COLLATE NOCASE ASC")){if(c!=null)while(c.moveToNext()){long id=c.getLong(0);String title=safe(c.getString(1),"未知歌曲"),artist=safe(c.getString(2),"未知艺人"),album=safe(c.getString(3),"未知专辑"),path=c.getString(5),uri=ContentUris.withAppendedId(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,id).toString();long modified=c.getLong(6);if(!database.unchanged(uri,modified))database.upsert(uri,title,artist,album,c.getLong(4),modified,coverPath(path),lrcPath(path));n++;if(n%10==0)statusMessage("扫描中 · 已检查 "+n+" 首");}}loadData();});}
    private void statusMessage(String m){runOnUiThread(()->{if(status!=null)status.setText(m);else Toast.makeText(this,m,Toast.LENGTH_SHORT).show();});}
    private String coverPath(String p){File f=CoverResolver.sidecar(p);return f==null?null:f.getAbsolutePath();}
    private String lrcPath(String p){if(p==null)return null;File a=new File(p),f=new File(a.getParentFile(),a.getName().replaceFirst("\\.[^.]+$","")+".lrc");return f.isFile()?f.getAbsolutePath():null;}
    private String safe(String v,String f){return v==null||v.trim().isEmpty()||"<unknown>".equalsIgnoreCase(v)?f:v;}
    private void play(LibraryDbHelper.Track target,List<LibraryDbHelper.Track> queue){int index=-1;for(int i=0;i<tracks.size();i++)if(tracks.get(i).uri.equals(target.uri))index=i;playingIndex=index;ArrayList<String> u=new ArrayList<>(),t=new ArrayList<>(),a=new ArrayList<>();for(LibraryDbHelper.Track x:queue){u.add(x.uri);t.add(x.title);a.add(x.artist);}Intent in=new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_PLAY).putExtra(PlaybackService.EXTRA_URI,target.uri).putExtra(PlaybackService.EXTRA_TITLE,target.title).putExtra(PlaybackService.EXTRA_ARTIST,target.artist).putStringArrayListExtra(PlaybackService.EXTRA_QUEUE_URI,u).putStringArrayListExtra(PlaybackService.EXTRA_QUEUE_TITLE,t).putStringArrayListExtra(PlaybackService.EXTRA_QUEUE_ARTIST,a).putExtra(PlaybackService.EXTRA_QUEUE_INDEX,Math.max(0,queue.indexOf(target)));if(Build.VERSION.SDK_INT>=26)startForegroundService(in);else startService(in);database.addHistory(target.uri);showMiniPlayer(target);loadData();}
    private void showMiniPlayer(LibraryDbHelper.Track track){if(miniPlayer==null)return;miniPlayer.removeAllViews();miniPlayer.setVisibility(View.VISIBLE);TextView copy=text(track.title+"\n"+track.artist,13,TEXT);miniPlayer.addView(copy,lp(0,dp(52),1));Button open=button("详情");open.setOnClickListener(v->switchPage(4));miniPlayer.addView(open,lp(dp(64),dp(48)));Button toggle=button("播放");toggle.setOnClickListener(v->startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_TOGGLE)));miniPlayer.addView(toggle,lp(dp(76),dp(48)));}
    private boolean hasAudioPermission(){return Build.VERSION.SDK_INT<33?checkSelfPermission(Manifest.permission.READ_EXTERNAL_STORAGE)==PackageManager.PERMISSION_GRANTED:checkSelfPermission(Manifest.permission.READ_MEDIA_AUDIO)==PackageManager.PERMISSION_GRANTED;}
    private void requestAudioPermission(){requestPermissions(Build.VERSION.SDK_INT<33?new String[]{Manifest.permission.READ_EXTERNAL_STORAGE}:new String[]{Manifest.permission.READ_MEDIA_AUDIO,Manifest.permission.POST_NOTIFICATIONS},REQUEST_AUDIO);}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQUEST_AUDIO&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)loadData();}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout row(){return new LinearLayout(this);}
    private TextView text(String v,int s,int c){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);t.setLineSpacing(0,1.15f);return t;}
    private Button button(String v){Button b=new Button(this);b.setText(v);b.setTextSize(13);b.setTextColor(BG);b.setAllCaps(false);b.setMinHeight(0);b.setMinWidth(0);b.setBackground(glassBackground(MINT));b.setOnTouchListener((view,event)->{if(event.getAction()==MotionEvent.ACTION_DOWN){view.animate().scaleX(.97f).scaleY(.97f).setDuration(70).start();view.performHapticFeedback(android.view.HapticFeedbackConstants.VIRTUAL_KEY);}else if(event.getAction()==MotionEvent.ACTION_UP||event.getAction()==MotionEvent.ACTION_CANCEL)view.animate().scaleX(1f).scaleY(1f).setDuration(100).start();return false;});return b;}
    private GradientDrawable glassBackground(int color){GradientDrawable drawable=new GradientDrawable();drawable.setColor(Color.argb(218,Color.red(color),Color.green(color),Color.blue(color)));drawable.setCornerRadius(dp(16));drawable.setStroke(dp(1),Color.argb(95,255,255,255));return drawable;}
    private LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w,h);}
    private LinearLayout.LayoutParams lp(int w,int h,float weight){return new LinearLayout.LayoutParams(w,h,weight);}
    private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
    @Override protected void onDestroy(){try{unregisterReceiver(progressReceiver);}catch(IllegalArgumentException ignored){}executor.shutdownNow();database.close();super.onDestroy();}
}
